options.customCss:
:root {
  /* Colors */
  --chat--color-primary: #e20015;
  --chat--color-primary-shade-50: #b00010;
  --chat--color-primary-shade-100: #8a000c;
  --chat--color-secondary: #005691;
  --chat--color-secondary-shade-50: #004270;
  --chat--color-white: #ffffff;
  --chat--color-light: #eff1f2;
  --chat--color-light-shade-50: #e0e2e5;
  --chat--color-light-shade-100: #c1c4c9;
  --chat--color-medium: #777777;
  --chat--color-dark: #000000;
  --chat--color-disabled: #d2d4d9;
  --chat--color-typing: #404040;

  /* Base Layout */
  --chat--spacing: 1rem;
  --chat--border-radius: 0px;
  --chat--transition-duration: 0.15s;
  --chat--font-family: Arial, Helvetica, sans-serif;

  /* Window Dimensions */
  --chat--window--width: 400px;
  --chat--window--height: 600px;
  --chat--window--bottom: var(--chat--spacing);
  --chat--window--right: var(--chat--spacing);
  --chat--window--z-index: 9999;
  --chat--window--border: 1px solid var(--chat--color-light-shade-50);
  --chat--window--border-radius: var(--chat--border-radius);
  --chat--window--margin-bottom: var(--chat--spacing);

  /* Header Styles */
  --chat--header-height: auto;
  --chat--header--padding: var(--chat--spacing);
  --chat--header--background: var(--chat--color-primary);
  --chat--header--color: var(--chat--color-white);
  --chat--header
